 package approval

-import "time"
+import (
+	"crypto/hmac"
+	"crypto/sha256"
+	"encoding/base64"
+	"errors"
+	"strings"
+	"time"
+)
+
+const minSecretLen = 32

 func Sign(secret []byte, taskID, actor string, expires time.Time) (string, error) {
-	return "", nil
+	if len(secret) < minSecretLen {
+		return "", errors.New("approval: secret must be at least 32 bytes")
+	}
+	if taskID == "" {
+		return "", errors.New("approval: taskID must not be empty")
+	}
+	if actor == "" {
+		return "", errors.New("approval: actor must not be empty")
+	}
+
+	payload := taskID + "|" + actor + "|" + expires.UTC().Format(time.RFC3339)
+	mac := hmac.New(sha256.New, secret)
+	mac.Write([]byte(payload))
+	sig := mac.Sum(nil)
+
+	token := base64.URLEncoding.EncodeToString([]byte(payload)) + "." + base64.URLEncoding.EncodeToString(sig)
+	return token, nil
 }

 func Verify(secret []byte, token, taskID string, now time.Time) (string, error) {
-	return "", nil
+	if len(secret) < minSecretLen {
+		return "", errors.New("approval: secret must be at least 32 bytes")
+	}
+
+	parts := strings.Split(token, ".")
+	if len(parts) != 2 {
+		return "", errors.New("approval: malformed token")
+	}
+
+	payloadBytes, err := base64.URLEncoding.DecodeString(parts[0])
+	if err != nil {
+		return "", errors.New("approval: malformed token payload")
+	}
+	sig, err := base64.URLEncoding.DecodeString(parts[1])
+	if err != nil {
+		return "", errors.New("approval: malformed token signature")
+	}
+
+	mac := hmac.New(sha256.New, secret)
+	mac.Write(payloadBytes)
+	expectedSig := mac.Sum(nil)
+	if !hmac.Equal(sig, expectedSig) {
+		return "", errors.New("approval: signature mismatch")
+	}
+
+	fields := strings.Split(string(payloadBytes), "|")
+	if len(fields) != 3 {
+		return "", errors.New("approval: malformed token payload")
+	}
+	tokenTaskID, actor, expiresStr := fields[0], fields[1], fields[2]
+
+	if tokenTaskID != taskID {
+		return "", errors.New("approval: token is for a different task")
+	}
+
+	expires, err := time.Parse(time.RFC3339, expiresStr)
+	if err != nil {
+		return "", errors.New("approval: malformed token expiry")
+	}
+
+	if expires.UTC().Before(now.UTC()) {
+		return "", errors.New("approval: token has expired")
+	}
+
+	return actor, nil
 }
